INSERT INTO grammar.content_catalog_topics(version,slug,catalog_hash,payload) VALUES('core-2026-09-v3','adverbs-position','e49c6c64b6333354230b05b223ded19e0e7519c1828bf3f36aee778f9f3f39c4','{"slug":"adverbs-position","title":"Adverbs of frequency, manner and position","level":"A2","order":24,"summary":"Describe how often and how an action happens, while placing the adverb where its meaning is clear.","guidance":"Read the form and meaning together. Study the contrasts, then explain a worked example in your own words before starting a fresh practice session.","learningGoals":["Frequency before the main verb","After be and after the first auxiliary","Manner and adjective forms","Keep the object beside its verb"],"rules":[{"title":"Frequency before the main verb","explanation":"Frequency adverbs such as usually, often and never normally go before an ordinary lexical verb. Their position may shift for focus, but neutral order gives a reliable starting point. Never is already negative in meaning.","pattern":"She **usually walks**. / They **never complain**.","commonMistakes":["Do not add not merely because never is negative: they never complain is already negative in meaning."],"examples":["Choose neutral word order for a routine involving the visitor guide. → **She usually prepares the visitor guide.**","Choose neutral word order for a routine involving the old portrait. → **She usually restores the old portrait.**"],"skill":"form"},{"title":"After be and after the first auxiliary","explanation":"With main-verb be, a frequency adverb usually follows be. With a multi-part verb phrase, it often follows the first auxiliary. Always can appear in other positions for emphasis; these are neutral-order exercises.","pattern":"She is **usually** early. / They have **often** visited.","commonMistakes":["She usually is early can be emphatic, so a neutral-order instruction is needed when comparing positions."],"examples":["Use the adverb, not the adjective: “The assistant is **usually** ready to prepare the visitor guide.”","Use the adverb, not the adjective: “The assistant is **usually** ready to restore the old portrait.”"],"skill":"meaning"},{"title":"Manner and adjective forms","explanation":"A manner adverb describes how an action is done. Many are formed with -ly, but not all: fast and hard are common adverbs without -ly. An adjective usually describes a noun or follows a linking verb.","pattern":"They worked **carefully**. / The work was **careful**.","commonMistakes":["Hard means with effort; hardly means almost not. They are not ordinary form variants with the same meaning."],"examples":["Describe the action’s manner: “They prepare the visitor guide **carefully**.”","Describe the action’s manner: “They restore the old portrait **carefully**.”"],"skill":"contrast"},{"title":"Keep the object beside its verb","explanation":"A short manner adverb often goes after the object, or before the main verb. Do not normally put it between a transitive verb and its direct object. Position also changes scope: only can focus on different parts of a sentence.","pattern":"She read **the letter carefully**.","commonMistakes":["She read carefully the letter is awkward neutral order; put carefully after the object or before read."],"examples":["Keep the object beside the verb in this neutral sentence about the visitor guide. → **They prepared the visitor guide carefully.**","Keep the object beside the verb in this neutral sentence about the old portrait. → **They restored the old portrait carefully.**"],"skill":"application"}],"tips":[],"source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-adverbials"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"quizItems":[{"id":"de5147ea-989f-561a-aad6-efa97fefdae2","topicSlug":"adverbs-position","level":"A2","prompt":"Choose neutral word order for a routine involving the visitor guide.","choices":[{"id":"A","text":"She usually prepares the visitor guide."},{"id":"B","text":"She prepares usually the visitor guide."},{"id":"C","text":"She prepares the visitor guide usuallys."},{"id":"D","text":"She usual prepares the visitor guide."}],"answerId":"A","hint":"Place **usually before the main lexical verb**, while keeping verb and object together.","explanation":"The frequency adverb **usually** normally precedes the lexical verb in neutral order.","keywords":["neutral-frequency"],"skill":"neutral-frequency","contextKey":"adverbs-position-1","fingerprint":"751d88248fdfdce01b06812870cf3e68ee56038f48ed3c565aadc287ffc8410b","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-adverbials"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Place **usually before the main lexical verb**, while keeping verb and object together.","The frequency adverb **usually** normally precedes the lexical verb in neutral order.","Choose **She usually prepares the visitor guide.**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"The frequency adverb **usually** normally precedes the lexical verb in neutral order.","B":"This puts usually between the transitive verb and its object.","C":"Usually is an adverb and does not take an -s agreement ending.","D":"Usual is an adjective; this position requires the adverb usually."}}},{"id":"26a8cbc7-952d-57e4-ac4f-56ccf7e8e438","topicSlug":"adverbs-position","level":"A2","prompt":"Use the adverb, not the adjective: “The assistant is ____ ready to prepare the visitor guide.”","choices":[{"id":"A","text":"usually"},{"id":"B","text":"usual"},{"id":"C","text":"usuals"},{"id":"D","text":"usualness"}],"answerId":"A","hint":"The blank modifies how often the assistant is ready, so it needs a **frequency adverb**.","explanation":"After be, **usually** gives the frequency of the state ready.","keywords":["frequency-after-be"],"skill":"frequency-after-be","contextKey":"adverbs-position-1","fingerprint":"2dde3a95813477122167a663e42af8de94c31e3202d099a1f1cf163f1a0cb77a","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-adverbials"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["The blank modifies how often the assistant is ready, so it needs a **frequency adverb**.","After be, **usually** gives the frequency of the state ready.","Choose **usually**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"After be, **usually** gives the frequency of the state ready.","B":"Usual is an adjective and cannot modify ready as a frequency adverb here.","C":"Usuals is not the frequency adverb.","D":"A noun naming a quality does not supply the needed frequency adverb."}}},{"id":"f33ce589-516e-5fb2-a8a5-d85e5e80fa2b","topicSlug":"adverbs-position","level":"A2","prompt":"Describe the action’s manner: “They prepare the visitor guide ____.”","choices":[{"id":"A","text":"care"},{"id":"B","text":"carefully"},{"id":"C","text":"careful"},{"id":"D","text":"carefulness"}],"answerId":"B","hint":"Ask **how?** about the action, rather than asking what the person is like.","explanation":"**Carefully** tells us how they perform the action.","keywords":["manner-adverb"],"skill":"manner-adverb","contextKey":"adverbs-position-1","fingerprint":"7287675481ae502c381f04e779c943b336441e936765227fa67aca50f28315dc","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-adverbials"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Ask **how?** about the action, rather than asking what the person is like.","**Carefully** tells us how they perform the action.","Choose **carefully**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"Care is not the required manner adverb.","B":"**Carefully** tells us how they perform the action.","C":"Careful is an adjective; the task asks for an adverb describing the action.","D":"Carefulness is a noun, not a manner adverb."}}},{"id":"f75d4f4f-2e09-5987-a033-91f7b333f051","topicSlug":"adverbs-position","level":"A2","prompt":"Keep the object beside the verb in this neutral sentence about the visitor guide.","choices":[{"id":"A","text":"They careful prepared the visitor guide."},{"id":"B","text":"They prepared the visitor guide carefulness."},{"id":"C","text":"They prepared the visitor guide carefully."},{"id":"D","text":"They prepared carefully the visitor guide."}],"answerId":"C","hint":"Keep **verb + object** together, then add the manner adverb.","explanation":"The direct object follows the verb, and **carefully** follows the object.","keywords":["manner-word-order"],"skill":"manner-word-order","contextKey":"adverbs-position-1","fingerprint":"3cad4aab0b76d536ce7c78d85b88b4bdb3e4ee14abeaa9d0aaafa072b0c6ed8a","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-adverbials"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Keep **verb + object** together, then add the manner adverb.","The direct object follows the verb, and **carefully** follows the object.","Choose **They prepared the visitor guide carefully.**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"Careful is an adjective, not the adverb needed here.","B":"Carefulness is a noun and does not modify the action in this position.","C":"The direct object follows the verb, and **carefully** follows the object.","D":"The adverb separates the transitive verb from its object in an awkward neutral order."}}},{"id":"8ae52923-fd57-5284-a045-635909cef6c9","topicSlug":"adverbs-position","level":"A2","prompt":"Choose neutral word order for a routine involving the old portrait.","choices":[{"id":"A","text":"She usually restores the old portrait."},{"id":"B","text":"She restores usually the old portrait."},{"id":"C","text":"She restores the old portrait usuallys."},{"id":"D","text":"She usual restores the old portrait."}],"answerId":"A","hint":"Place **usually before the main lexical verb**, while keeping verb and object together.","explanation":"The frequency adverb **usually** normally precedes the lexical verb in neutral order.","keywords":["neutral-frequency"],"skill":"neutral-frequency","contextKey":"adverbs-position-2","fingerprint":"af360acacf1122becbe981a1fa97a987a3fb26f750600018b3b30a4ef6a9937f","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-adverbials"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Place **usually before the main lexical verb**, while keeping verb and object together.","The frequency adverb **usually** normally precedes the lexical verb in neutral order.","Choose **She usually restores the old portrait.**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"The frequency adverb **usually** normally precedes the lexical verb in neutral order.","B":"This puts usually between the transitive verb and its object.","C":"Usually is an adverb and does not take an -s agreement ending.","D":"Usual is an adjective; this position requires the adverb usually."}}},{"id":"05c40ffc-4370-57a5-aee4-8a95ce03a954","topicSlug":"adverbs-position","level":"A2","prompt":"Use the adverb, not the adjective: “The assistant is ____ ready to restore the old portrait.”","choices":[{"id":"A","text":"usuals"},{"id":"B","text":"usualness"},{"id":"C","text":"usually"},{"id":"D","text":"usual"}],"answerId":"C","hint":"The blank modifies how often the assistant is ready, so it needs a **frequency adverb**.","explanation":"After be, **usually** gives the frequency of the state ready.","keywords":["frequency-afte